#!/usr/bin/env python3
# SPDX-License-Identifier: LGPL-2.1-or-later
"""Our own noise scene pack: .local/library_free.muk, synthesised from nothing (CC0, "generated by this project"). Pure stdlib, deterministic
(fixed seeds, no clock): the same bytes every run. Format = what app/main/noise_engine.c reads: a STORED zip with default_scenes.json,
seed.json and "<sha256>.flac" entries (mono 16-bit FLAC, seamless loops). The firmware looks for /sdcard/sleep/library.muk, so the card
template zip carries this file under that name. The audio never goes into git (.local/ is ignored).
usage: make_noise_pack.py [--out FILE] [--list]"""
import argparse, hashlib, json, math, os, random, struct, sys, zipfile

REPO = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
OUT = os.path.join(REPO, ".local", "library_free.muk")
XF = 0.75          # seconds of the wrap crossfade that makes the loop seamless

# ------------------------------------------------------------------ DSP helpers (lists of floats)
def white(rng, n): return [rng.uniform(-1.0, 1.0) for _ in range(n)]

def lp1(x, fc, sr):
    a = 1.0 - math.exp(-2.0 * math.pi * fc / sr); y = 0.0; o = []
    for v in x: y += a * (v - y); o.append(y)
    return o

def hp1(x, fc, sr):
    l = lp1(x, fc, sr); return [a - b for a, b in zip(x, l)]

def svf_bp(x, fcs, q, sr):
    """state-variable band-pass; fcs = per-sample centre frequency list (or a number)"""
    lo = bd = 0.0; o = []; inv = 1.0 / q
    for i, v in enumerate(x):
        fc = fcs[i] if isinstance(fcs, list) else fcs
        f = 2.0 * math.sin(math.pi * min(fc, sr * 0.2) / sr)
        lo += f * bd; hi = v - lo - inv * bd; bd += f * hi; o.append(bd)
    return o

def pink(x):
    b0 = b1 = b2 = b3 = b4 = b5 = b6 = 0.0; o = []
    for w in x:
        b0 = 0.99886 * b0 + w * 0.0555179; b1 = 0.99332 * b1 + w * 0.0750759; b2 = 0.96900 * b2 + w * 0.1538520
        b3 = 0.86650 * b3 + w * 0.3104856; b4 = 0.55000 * b4 + w * 0.5329522; b5 = -0.7616 * b5 - w * 0.0168980
        o.append(b0 + b1 + b2 + b3 + b4 + b5 + b6 + w * 0.5362); b6 = w * 0.115926
    return o

def brown(x):
    y = 0.0; o = []
    for w in x: y = 0.998 * y + w * 0.05; o.append(y)
    return o

def periodic(n, sr, L, cycles, phase=0.0):
    """sin with an integer number of cycles per loop of L samples: the loop stays seamless"""
    return [math.sin(2 * math.pi * (cycles * i / L + phase)) for i in range(n)]

def seam(x, L, sr):
    """x has L + X samples; the extra X fade into the first X so that sample L-1 -> 0 is as continuous as the noise itself"""
    X = len(x) - L
    o = x[:L]
    for i in range(X):
        t = (i + 0.5) / X; a = math.sin(t * math.pi / 2); b = math.cos(t * math.pi / 2)
        o[i] = x[i] * a + x[L + i] * b
    return o

def wrap_add(buf, start, ev, gain=1.0):
    """add an event circularly: nothing falls off the end, so event-based loops are seamless"""
    n = len(buf)
    for k, v in enumerate(ev): buf[(start + k) % n] += gain * v

def normalise(x, rms=0.12, peak=0.92):
    m = sum(v * v for v in x) / len(x); r = math.sqrt(m) or 1.0
    s = min(rms / r, peak / (max(abs(v) for v in x) or 1.0))
    return [v * s for v in x]

# ------------------------------------------------------------------ the sounds: name -> (rate, seconds, builder(rng, n, sr, L) -> n samples)
def s_white(rng, n, sr, L): return white(rng, n)
def s_pink(rng, n, sr, L): return pink(white(rng, n))
def s_brown(rng, n, sr, L): return brown(white(rng, n))
def s_fan(rng, n, sr, L):
    body = lp1(pink(white(rng, n)), 1500, sr); T = L / sr
    f0 = round(95 * T) / T                                    # whole cycles per loop
    hum = [0.0] * n
    for k, g in ((1, 0.30), (2, 0.18), (3, 0.10), (5, 0.05)):
        ph = periodic(n, sr, L, round(f0 * T) * k, rng.random())
        hum = [h + g * p for h, p in zip(hum, ph)]
    wob = periodic(n, sr, L, 3)
    return [b * 0.6 + h * (0.55 + 0.1 * w) for b, h, w in zip(body, hum, wob)]
def s_rumble(rng, n, sr, L): return lp1(lp1(brown(white(rng, n)), 140, sr), 140, sr)

def s_rain(rng, n, sr, L):
    bed = hp1(lp1(white(rng, n), 7000, sr), 900, sr)
    slow = periodic(n, sr, L, 2); bed = [b * (0.8 + 0.12 * s) for b, s in zip(bed, slow)]
    out = [0.0] * L
    drops = [0.0] * L
    for _ in range(int(L / sr * 120)):                        # drops: a short ringing tick, 2.5-7 kHz
        f = rng.uniform(2500, 7000); a = rng.random() ** 2.2; d = rng.uniform(0.0015, 0.006); ph = rng.random() * 6.28
        ev = [math.sin(ph + 2 * math.pi * f * k / sr) * math.exp(-k / (d * sr)) for k in range(int(d * sr * 5))]
        wrap_add(drops, rng.randrange(L), ev, a)
    return [bed[i] * 0.35 + drops[i % L] * 1.3 if i < L else bed[i] * 0.35 + drops[i - L] * 1.3 for i in range(n)]

def s_waves(rng, n, sr, L):
    base = pink(white(rng, n)); lo = lp1(base, 500, sr)
    env = [0.0] * n
    for cyc, ph, g in ((2, 0.1, 1.0), (3, 0.55, 0.45)):
        p = periodic(n, sr, L, cyc, ph); env = [e + g * (0.5 + 0.5 * v) for e, v in zip(env, p)]
    m = max(env); env = [(e / m) ** 2.4 for e in env]
    foam = svf_bp(white(rng, n), [1200 + 2600 * e for e in env], 1.2, sr)
    return [lo[i] * (0.25 + 0.75 * env[i]) * 1.6 + foam[i] * env[i] * 0.55 for i in range(n)]

def s_wind(rng, n, sr, L):
    fc = [380 + 260 * a + 90 * b for a, b in zip(periodic(n, sr, L, 3, 0.2), periodic(n, sr, L, 7, 0.6))]
    body = svf_bp(white(rng, n), fc, 1.6, sr)
    gust = [0.35 + 0.65 * (0.5 + 0.5 * v) ** 1.5 for v in periodic(n, sr, L, 2, 0.3)]
    gust2 = [0.8 + 0.2 * v for v in periodic(n, sr, L, 5, 0.9)]
    whistle = svf_bp(white(rng, n), [1500 + 500 * v for v in periodic(n, sr, L, 4, 0.5)], 12.0, sr)
    return [(body[i] * 1.0 + whistle[i] * 0.35) * gust[i] * gust2[i] for i in range(n)]

def s_stream(rng, n, sr, L):
    bed = lp1(pink(white(rng, n)), 3500, sr)
    gur = svf_bp(white(rng, n), [700 + 250 * v for v in periodic(n, sr, L, 9, 0.1)], 2.5, sr)
    bub = [0.0] * L
    for _ in range(int(L / sr * 70)):                         # bubbles: a rising sine chirp, 0.6 -> ~1.6 kHz
        f = rng.uniform(500, 1500); a = rng.uniform(0.2, 1.0); d = rng.uniform(0.012, 0.035)
        m = int(d * sr * 4); ph = 0.0; ev = []
        for k in range(m):
            t = k / sr; ph += 2 * math.pi * f * (1 + 14 * t) / sr; ev.append(math.sin(ph) * math.exp(-t / d) * (1 - math.exp(-k / 6.0)))
        wrap_add(bub, rng.randrange(L), ev, a)
    return [bed[i] * 0.45 + gur[i] * 0.35 + bub[i % L] * 0.45 for i in range(n)]

def s_campfire(rng, n, sr, L):
    room = lp1(brown(white(rng, n)), 220, sr)
    flick = lp1(white(rng, n), 4, sr); m = max(abs(v) for v in flick) or 1.0
    hiss = svf_bp(white(rng, n), 3200, 0.8, sr)
    body = [room[i] * 1.3 + hiss[i] * 0.10 * (1.0 + 2.0 * flick[i] / m) for i in range(n)]
    cr = [0.0] * L
    for _ in range(int(L / sr * 26)):                         # crackles: 1-5 ms noise bursts, mostly small, a few loud pops
        a = rng.random() ** 3 * 1.6 + 0.03; d = rng.uniform(0.0008, 0.005); f = rng.uniform(1500, 6000)
        ev = [rng.uniform(-1, 1) * math.exp(-k / (d * sr)) for k in range(int(d * sr * 5))]
        wrap_add(cr, rng.randrange(L), svf_bp(ev, f, 1.5, sr), a * 3.0)
    for _ in range(int(L / sr * 1.2)):                        # pops with a short low thump
        d = 0.012; ev = [math.sin(2 * math.pi * rng.uniform(110, 190) * k / sr) * math.exp(-k / (d * sr)) for k in range(int(d * sr * 5))]
        wrap_add(cr, rng.randrange(L), ev, rng.uniform(0.3, 0.7))
    return [body[i] + cr[i % L] * 0.9 for i in range(n)]

def s_insects(rng, n, sr, L):
    bed = hp1(lp1(white(rng, n), 2500, sr), 300, sr)
    out = [bed[i] * 0.025 for i in range(L)]
    for freq, period, pulses in ((4300, 0.83, 4), (3700, 1.11, 3), (5100, 0.67, 5), (4700, 1.37, 3)):
        per = L / sr / round(L / sr / period)                 # whole chirps per loop
        t = rng.random() * per
        while t < L / sr:
            for p in range(pulses):
                st = t + p * 0.032; m = int(0.016 * sr); ph = rng.random() * 6.28
                ev = [math.sin(ph + 2 * math.pi * freq * k / sr) * math.sin(math.pi * k / m) ** 2 for k in range(m)]
                wrap_add(out, int(st * sr) % L, ev, 0.5)
            t += per
    return [out[i % L] if i < L else out[i - L] for i in range(n)]

# id, zh_tw, zh_cn, en, rate, seconds, builder, category index
SOUNDS = [
    ("white",    "白噪音",   "白噪音",   "White noise", 22050, 6, s_white, 0),
    ("pink",     "粉紅噪音", "粉红噪音", "Pink noise",  22050, 6, s_pink, 0),
    ("brown",    "棕色噪音", "棕色噪音", "Brown noise", 16000, 6, s_brown, 0),
    ("fan",      "風扇聲",   "风扇声",   "Fan hum",     16000, 8, s_fan, 0),
    ("rumble",   "低頻轟鳴", "低频轰鸣", "Deep rumble", 11025, 8, s_rumble, 0),
    ("rain",     "雨聲",     "雨声",     "Rain",        22050, 10, s_rain, 1),
    ("waves",    "海浪",     "海浪",     "Ocean waves", 22050, 10, s_waves, 1),
    ("wind",     "風聲",     "风声",     "Wind",        22050, 10, s_wind, 1),
    ("stream",   "溪流",     "溪流",     "Stream",      22050, 10, s_stream, 1),
    ("campfire", "營火劈啪", "营火噼啪", "Campfire crackle", 22050, 10, s_campfire, 1),
    ("insects",  "夜晚蟲鳴", "夜晚虫鸣", "Night insects", 22050, 10, s_insects, 1),
]
CATS = ("噪音", "自然")
CATS_EN = ("Noise", "Nature")
# scenes: id, zh_tw, zh_cn, en, [(sound id, volume)]
SCENES = [
    ("n-white",  "白噪音",     "白噪音",     "White noise",  [("white", 0.8)]),
    ("n-pink",   "粉紅噪音",   "粉红噪音",   "Pink noise",   [("pink", 0.9)]),
    ("n-brown",  "棕色噪音",   "棕色噪音",   "Brown noise",  [("brown", 1.0)]),
    ("n-fan",    "電風扇",     "电风扇",     "Electric fan", [("fan", 1.0), ("rumble", 0.5)]),
    ("n-deep",   "深沉睡眠",   "深沉睡眠",   "Deep sleep",   [("rumble", 0.9), ("pink", 0.35)]),
    ("n-soft",   "柔和氣流",   "柔和气流",   "Soft airflow", [("pink", 0.5), ("fan", 0.6), ("white", 0.12)]),
    ("s-rain",   "雨夜",       "雨夜",       "Rainy night",  [("rain", 1.0), ("rumble", 0.4)]),
    ("s-sea",    "海邊",       "海边",       "Seaside",      [("waves", 1.0), ("wind", 0.35)]),
    ("s-wind",   "起風了",     "起风了",     "Windy",        [("wind", 1.0), ("rumble", 0.3)]),
    ("s-creek",  "山間溪流",   "山间溪流",   "Mountain creek", [("stream", 1.0), ("insects", 0.25)]),
    ("s-fire",   "營火之夜",   "营火之夜",   "Campfire night", [("campfire", 1.0), ("insects", 0.4), ("wind", 0.15)]),
    ("s-summer", "夏夜",       "夏夜",       "Summer night", [("insects", 0.9), ("stream", 0.4)]),
]

# ------------------------------------------------------------------ FLAC (mono 16-bit, fixed predictors + Rice; no external tool)
def crc8(b):
    c = 0
    for x in b:
        c ^= x
        for _ in range(8): c = ((c << 1) ^ 0x07) & 0xFF if c & 0x80 else (c << 1) & 0xFF
    return c

_T16 = []
for _i in range(256):
    _c = _i << 8
    for _ in range(8): _c = ((_c << 1) ^ 0x8005) & 0xFFFF if _c & 0x8000 else (_c << 1) & 0xFFFF
    _T16.append(_c)
def crc16(b):
    c = 0
    for x in b: c = ((c << 8) & 0xFFFF) ^ _T16[(c >> 8) ^ x]
    return c

class Bits:
    def __init__(s): s.v = 0; s.n = 0
    def put(s, val, bits): s.v = (s.v << bits) | (val & ((1 << bits) - 1)); s.n += bits
    def unary_rice(s, u, k):
        q = u >> k; s.v = (s.v << (q + 1)) | 1; s.n += q + 1
        if k: s.put(u & ((1 << k) - 1), k)
    def bytes(s):
        pad = (-s.n) % 8; v = s.v << pad
        return v.to_bytes((s.n + pad) // 8, "big")

def _resid(x, order):
    if order == 0: return list(x)
    if order == 1: return [x[i] - x[i - 1] for i in range(1, len(x))]
    if order == 2: return [x[i] - 2 * x[i - 1] + x[i - 2] for i in range(2, len(x))]
    if order == 3: return [x[i] - 3 * x[i - 1] + 3 * x[i - 2] - x[i - 3] for i in range(3, len(x))]
    return [x[i] - 4 * x[i - 1] + 6 * x[i - 2] - 4 * x[i - 3] + x[i - 4] for i in range(4, len(x))]

def _rice_cost(u, k): return sum(v >> k for v in u) + len(u) * (k + 1)

def _partition(u, k_guess_sum):
    best = None
    for k in range(15):
        c = _rice_cost(u, k)
        if best is None or c < best[0]: best = (c, k)
        elif c > best[0] + 64: break
    return best

def _subframe(x):
    n = len(x); best = None
    for order in range(5):
        if n <= order + 1: break
        r = _resid(x, order)
        if best is None or sum(abs(v) for v in r) < best[0]: best = (sum(abs(v) for v in r), order, r)
    _, order, r = best
    u = [(v << 1) if v >= 0 else ((-v << 1) - 1) for v in r]
    plan = None
    for po in range(0, 7):
        if n % (1 << po) or n // (1 << po) <= order: break
        size = n >> po; parts = []; pos = 0; cost = 6
        for p in range(po and (1 << po) or 1):
            ln = size - order if p == 0 else size
            c, k = _partition(u[pos:pos + ln], 0); parts.append((pos, ln, k)); pos += ln; cost += c + 4
        if plan is None or cost < plan[0]: plan = (cost, po, parts)
    cost, po, parts = plan
    ver = 8 + 16 * n  # verbatim fallback if worse
    b = Bits(); b.put(0, 1); b.put(8 + order, 6); b.put(0, 1)
    for v in x[:order]: b.put(v, 16)
    b.put(0, 2); b.put(po, 4)
    for pos, ln, k in parts:
        b.put(k, 4)
        for v in u[pos:pos + ln]: b.unary_rice(v, k)
    if b.n > ver:
        b = Bits(); b.put(0, 1); b.put(1, 6); b.put(0, 1)
        for v in x: b.put(v, 16)
    return b

def _utf8(n):
    if n < 0x80: return bytes([n])
    if n < 0x800: return bytes([0xC0 | n >> 6, 0x80 | n & 0x3F])
    return bytes([0xE0 | n >> 12, 0x80 | (n >> 6) & 0x3F, 0x80 | n & 0x3F])

def flac_encode(pcm, rate, block=4096):
    n = len(pcm)
    si = struct.pack(">HH", block, block) + b"\0\0\0" + b"\0\0\0"
    pk = (rate << 44) | (0 << 41) | (15 << 36) | n
    si += pk.to_bytes(8, "big") + b"\0" * 16
    out = bytearray(b"fLaC" + bytes([0x80, 0, 0, 34]) + si)
    fn = 0
    for st in range(0, n, block):
        x = pcm[st:st + block]; ln = len(x)
        h = bytearray([0xFF, 0xF8])
        sr_code = {44100: 9, 48000: 10, 22050: 5, 16000: 8, 11025: 6}.get(rate, 0)   # others: from STREAMINFO (code 0)
        if ln == block: bs_code = 12; tail = b""
        else: bs_code = 7; tail = struct.pack(">H", ln - 1)
        h += bytes([(bs_code << 4) | sr_code, (0 << 4) | (4 << 1) | 0]) + _utf8(fn) + tail
        h.append(crc8(h))
        body = _subframe(x).bytes()
        fr = bytes(h) + body
        out += fr + struct.pack(">H", crc16(fr)); fn += 1
    return bytes(out)

# ------------------------------------------------------------------ build
def synth(sid, rate, secs, fn, seed):
    L = int(rate * secs); n = L + int(rate * XF)
    rng = random.Random(seed)
    x = fn(rng, n, rate, L)
    x = seam(x, L, rate)
    x = normalise(x)
    return [max(-32768, min(32767, int(round(v * 32767)))) for v in x], rate

def build():
    """-> (muk bytes, listing)"""
    ents = {}; tracks = []; sha = {}; info = []
    for i, (sid, tw, cn, en, rate, secs, fn, cat) in enumerate(SOUNDS):
        pcm, rate = synth(sid, rate, secs, fn, 1000 + i)
        data = flac_encode(pcm, rate)
        h = hashlib.sha256(data).hexdigest(); sha[sid] = h; ents[h + ".flac"] = data
        tracks.append({"sha256": h, "ext": ".flac", "zh_tw_name": tw, "zh_cn_name": cn, "en_name": en, "category": [CATS[cat]], "category_en": [CATS_EN[cat]]})
        info.append((sid, len(data), rate, secs))
    scenes = []
    for sid, tw, cn, en, layers in SCENES:
        scenes.append({"id": sid, "zh_tw_name": tw, "zh_cn_name": cn, "en_name": en,
                       "resolved_sounds": [{"sha256": sha[s], "volume": v} for s, v in layers], "unresolved_sound_ids": [], "fully_playable": True})
    ents["default_scenes.json"] = json.dumps({"scenes": scenes}, ensure_ascii=False, sort_keys=True, indent=0).encode()
    ents["seed.json"] = json.dumps({"tracks": tracks}, ensure_ascii=False, sort_keys=True, indent=0).encode()
    import io
    bio = io.BytesIO()
    with zipfile.ZipFile(bio, "w", zipfile.ZIP_STORED) as z:
        for name in sorted(ents):
            zi = zipfile.ZipInfo(name, (2026, 1, 1, 0, 0, 0)); zi.compress_type = zipfile.ZIP_STORED; zi.create_system = 3
            zi.external_attr = 0o100644 << 16
            z.writestr(zi, ents[name])
    return bio.getvalue(), info

def main():
    ap = argparse.ArgumentParser(); ap.add_argument("--out", default=OUT); ap.add_argument("--list", action="store_true")
    a = ap.parse_args()
    muk, info = build()
    for sid, size, rate, secs in info: print(f"  {sid:9s} {size:8d} B  {rate} Hz mono {secs} s")
    os.makedirs(os.path.dirname(os.path.abspath(a.out)), exist_ok=True)
    if not a.list: open(a.out, "wb").write(muk)
    print(f"{a.out}: {len(muk)} bytes, {len(SCENES)} scenes, {len(SOUNDS)} sounds, sha256 {hashlib.sha256(muk).hexdigest()[:16]}")

if __name__ == "__main__":
    main()
